export type Subscription = {
  __typename?: 'Subscription';
  /**
   * Job lifecycle events only — ADD (queued) and REMOVE (finished /
   * cancelled / failed). Delivered through a dedicated server-side pipeline
   * with a large buffer, so a client that subscribes to this never misses
   * an ADD even if it's concurrently slow to drain a separate
   * `jobsProgressSubscribe`.
   */
  jobsLifecycleSubscribe: JobStatusUpdate;
  /**
   * Job progress events only — UPDATE (status / progress / subtasks /
   * error). Lossy under backpressure by design: each UPDATE supersedes the
   * prior one, so the server prefers dropping an outdated tick over
   * blocking new lifecycle events behind it.
   */
  jobsProgressSubscribe: JobStatusUpdate;
  /**
   * Combined stream of all job-manager events. Retained for backwards
   * compatibility with existing clients; new clients should subscribe to
   * `jobsLifecycleSubscribe` and `jobsProgressSubscribe` separately so a
   * burst of progress UPDATEs cannot crowd out (and cause the server to
   * drop) the rarer-but-correctness-critical ADD / REMOVE events.
   */
  jobsSubscribe: JobStatusUpdate;
  loggingSubscribe: Array<LogEntry>;
  scanCompleteSubscribe: Scalars['Boolean']['output'];
};

